const llegada = Date.now();
const tema = /^telemetria\/([0-9A-F]{12})\/lecturas$/.exec(msg.topic);
if (!tema) {
    node.warn(`Tema no válido: ${msg.topic}`);
    return null;
}
let datos;
try {
    datos = JSON.parse(msg.payload);
} catch (error) {
    node.warn(`JSON mal formado en ${msg.topic}`);
    return null;
}
if (datos === null || typeof datos !== 'object' || Array.isArray(datos)) {
    node.warn(`La trama de ${msg.topic} no es un objeto JSON`);
    return null;
}
if (typeof datos.mac !== 'string') {
    node.warn(`La trama de ${msg.topic} no trae la MAC`);
    return null;
}
const mac = datos.mac.toUpperCase();
if (!/^([0-9A-F]{2}:){5}[0-9A-F]{2}$/.test(mac)) {
    node.warn(`MAC no válida en ${msg.topic}: ${datos.mac}`);
    return null;
}
if (mac.replace(/:/g, '') !== tema[1]) {
    node.warn(`La MAC ${mac} no coincide con el tema ${msg.topic}`);
    return null;
}
const decimal = (valor, min, max) =>
    typeof valor === 'number' && Number.isFinite(valor) && valor >= min && valor <= max ? valor : null;
const entero = (valor, min, max) => (Number.isInteger(valor) && valor >= min && valor <= max ? valor : null);
const lectura = {
    ts: entero(datos.ts, 1700000000000, 4102444800000),
    uptime: entero(datos.uptime, 0, 2147483647),
    temperatura: decimal(datos.temperatura, -40, 85),
    humedad: decimal(datos.humedad, 0, 100),
    presion: decimal(datos.presion, 300, 1100),
    mq135_v: decimal(datos.mq135_v, 0.05, 5),
    rssi: entero(datos.rssi, -127, 0),
    fw: typeof datos.fw === 'string' && datos.fw.length > 0 && datos.fw.length <= 32 ? datos.fw : null,
};
const invalidos = Object.keys(lectura).filter(
    (campo) => lectura[campo] === null && datos[campo] !== null && datos[campo] !== undefined,
);
if (invalidos.length > 0) {
    node.warn(`Campos no válidos de ${mac}, se guardan como nulos: ${invalidos.join(', ')}`);
}
msg.llegada = llegada;
msg.mac = mac;
msg.lectura = lectura;
msg.query = `SELECT d.id, d.estado, d.cliente_id, d.ubicacion_id, d.mq135_r0_kohm, u.cliente_id AS cliente_ubicacion
FROM dispositivos d
LEFT JOIN ubicaciones u ON u.id = d.ubicacion_id
WHERE d.mac_address = $1`;
msg.params = [mac];
return msg;

const disp = msg.payload[0];
if (!disp) {
    node.warn(`Monitor no registrado: ${msg.mac}`);
    return null;
}
if (disp.estado !== 'en_uso') {
    node.warn(`Monitor ${msg.mac} en estado ${disp.estado}: no se guardan sus lecturas`);
    return null;
}
if (disp.ubicacion_id === null) {
    node.warn(`Monitor ${msg.mac} en uso sin ubicación asignada`);
    return null;
}
if (disp.cliente_id !== disp.cliente_ubicacion) {
    node.warn(`La ubicación ${disp.ubicacion_id} no pertenece al cliente del monitor ${msg.mac}`);
    return null;
}
const l = msg.lectura;
const latencia = l.ts !== null && Math.abs(msg.llegada - l.ts) <= 10000 ? msg.llegada - l.ts : null;
const RL_EF = (1 * 30) / (1 + 30);
const r0 = disp.mq135_r0_kohm === null ? null : Number(disp.mq135_r0_kohm);
let rsR0 = null;
let nivel = null;
if (l.mq135_v !== null && l.mq135_v < 5 && r0 > 0) {
    const razon = Math.round(((RL_EF * (5 - l.mq135_v)) / l.mq135_v / r0) * 1000) / 1000;
    if (razon <= 999.999) {
        rsR0 = razon;
        nivel = razon >= 0.8 ? 'bueno' : razon >= 0.5 ? 'moderado' : 'malo';
    } else {
        node.warn(`Rs/R0 de ${msg.mac} fuera de rango (${razon}): revisar el R0 del monitor`);
    }
}
msg.calculado = { latencia, rsR0, nivel };
msg.query = `WITH monitor AS (
  UPDATE dispositivos
  SET ultima_lectura_en = GREATEST(ultima_lectura_en, to_timestamp($3 / 1000.0)),
      ultimo_rssi = CASE WHEN ultima_lectura_en > to_timestamp($3 / 1000.0) THEN ultimo_rssi
        ELSE COALESCE($13::smallint, ultimo_rssi) END,
      ultimo_uptime_s = CASE WHEN ultima_lectura_en > to_timestamp($3 / 1000.0) THEN ultimo_uptime_s
        ELSE COALESCE($12::integer, ultimo_uptime_s) END,
      fw = CASE WHEN ultima_lectura_en > to_timestamp($3 / 1000.0) THEN fw
        ELSE COALESCE($14::text, fw) END
  WHERE id = $1 AND estado = 'en_uso' AND ubicacion_id = $2
  RETURNING id, ubicacion_id
)
INSERT INTO lecturas (dispositivo_id, ubicacion_id, fecha_hora, ts_dispositivo, latencia_ms,
  temperatura, humedad, presion, mq135_v, rs_r0, nivel_aire, uptime_s)
SELECT id, ubicacion_id, to_timestamp($3 / 1000.0), to_timestamp($4 / 1000.0), $5::integer,
  $6::numeric, $7::numeric, $8::numeric, $9::numeric, $10::numeric, $11::text, $12::integer
FROM monitor
RETURNING id, dispositivo_id, ubicacion_id, fecha_hora`;
msg.params = [disp.id, disp.ubicacion_id, msg.llegada, l.ts, latencia, l.temperatura, l.humedad, l.presion,
    l.mq135_v, rsR0, nivel, l.uptime, l.rssi, l.fw];
return msg;

const fila = msg.payload[0];
if (!fila) {
    node.warn(`El monitor ${msg.mac} cambió de estado o de ubicación antes de guardar la lectura`);
    return null;
}
const l = msg.lectura;
msg.lecturaId = Number(fila.id);
msg.payload = {
    tipo: 'lectura',
    ubicacionId: fila.ubicacion_id,
    dispositivoId: fila.dispositivo_id,
    fecha: new Date(fila.fecha_hora).toISOString(),
    temperatura: l.temperatura,
    humedad: l.humedad,
    presion: l.presion,
    rsR0: msg.calculado.rsR0,
    nivelAire: msg.calculado.nivel ?? (l.mq135_v !== null ? 'sin_calibrar' : null),
};
delete msg.query;
delete msg.params;
delete msg.pgsql;
return msg;

if (!msg.sesion) return [null, msg];
const texto = msg.req.params.id;
const id = /^[1-9][0-9]{0,9}$/.test(texto) ? Number(texto) : null;
if (id === null || id > 2147483647) {
    msg.statusCode = 400;
    msg.payload = { mensaje: 'Ubicación no válida.' };
    return [null, msg];
}
msg.query = `SELECT d.id AS dispositivo_id, d.nombre, l.fecha_hora, l.temperatura, l.humedad, l.presion,
  l.mq135_v, l.rs_r0, l.nivel_aire,
  l.fecha_hora > now() - make_interval(secs => u.espera_sin_conexion_s) AS conectado
FROM ubicaciones u
LEFT JOIN dispositivos d ON d.ubicacion_id = u.id AND d.estado = 'en_uso'
LEFT JOIN LATERAL (
  SELECT fecha_hora, temperatura, humedad, presion, mq135_v, rs_r0, nivel_aire
  FROM lecturas
  WHERE dispositivo_id = d.id AND ubicacion_id = u.id
  ORDER BY fecha_hora DESC, id DESC
  LIMIT 1
) l ON true
WHERE u.id = $1 AND u.cliente_id = $2
ORDER BY d.id`;
msg.params = [id, msg.sesion.cliente];
return [msg, null];

if (msg.payload.length === 0) {
    msg.statusCode = 403;
    msg.payload = { mensaje: 'No tienes permiso.' };
    return msg;
}
const numero = (valor) => (valor === null ? null : Number(valor));
msg.payload = msg.payload
    .filter((f) => f.dispositivo_id !== null)
    .map((f) => ({
        dispositivoId: f.dispositivo_id,
        nombre: f.nombre,
        conectado: f.conectado === true,
        fecha: f.fecha_hora === null ? null : new Date(f.fecha_hora).toISOString(),
        temperatura: numero(f.temperatura),
        humedad: numero(f.humedad),
        presion: numero(f.presion),
        rsR0: numero(f.rs_r0),
        nivelAire: f.nivel_aire ?? (f.mq135_v !== null ? 'sin_calibrar' : null),
    }));
return msg;

node.error(`${msg.error.source.name || msg.error.source.type}: ${msg.error.message}`);
msg.statusCode = 500;
msg.payload = { mensaje: 'No se pudieron consultar los datos. Intenta de nuevo.' };
return msg;

const email = String(msg.payload?.email ?? '').trim().toLowerCase();
const clave = String(msg.payload?.clave ?? '');
if (!email || !clave) {
    msg.statusCode = 400;
    msg.payload = { mensaje: 'Escribe tu correo y tu contraseña.' };
    return [null, msg];
}
msg.clave = clave;
msg.query = `SELECT u.id, u.nombre, u.password_hash, u.debe_cambiar_clave, u.activo, r.nombre AS rol,
  c.id AS cliente_id, c.nombre AS organizacion, c.suspendido_en,
  (SELECT count(*) FROM dispositivos d WHERE d.cliente_id = c.id AND d.estado = 'en_uso')::int AS monitores,
  (SELECT count(*) FROM dispositivos d WHERE d.cliente_id = c.id AND d.estado = 'reservado')::int AS reservados
FROM usuarios u
JOIN roles r ON r.id = u.rol_id
LEFT JOIN clientes c ON c.id = u.cliente_id
WHERE u.email = $1`;
msg.params = [email];
return [msg, null];

const u = msg.payload[0];
const clave = msg.clave;
delete msg.clave;
const negar = (estado, mensaje) => {
    msg.statusCode = estado;
    msg.payload = { mensaje };
    return [msg, null];
};
const hash = u?.password_hash ?? '$2b$10$aTC7Sq47W4HsWDvtYeJak.SnUodQeZPAlZbavaVffbt2qy/184YSq';
const coincide = bcrypt.compareSync(clave, hash);
if (!u || !u.activo || !coincide) {
    return negar(401, 'Correo o contraseña incorrectos.');
}
if (u.suspendido_en) {
    return negar(403, 'Tu cuenta está suspendida. Comunícate con tu proveedor.');
}
const rol = u.rol === 'admin_plataforma' ? 'admin' : 'cliente';
const usuario = {
    id: u.id,
    nombre: u.nombre,
    organizacion: u.organizacion ?? 'TeleMon',
    rol,
    debeCambiarClave: u.debe_cambiar_clave,
    monitores: u.monitores ?? 0,
    monitoresReservados: u.reservados ?? 0,
};
const token = jwt.sign({ sub: u.id, rol, cliente: u.cliente_id }, env.get('JWT_SECRETO'), {
    algorithm: 'HS256',
    expiresIn: '12h',
});
msg.payload = { token, usuario };
return [msg, { query: 'UPDATE usuarios SET ultimo_login = now() WHERE id = $1', params: [u.id] }];

const cabecera = msg.req?.headers?.authorization ?? '';
const token = cabecera.startsWith('Bearer ') ? cabecera.slice(7) : '';
try {
    msg.sesion = jwt.verify(token, env.get('JWT_SECRETO'), { algorithms: ['HS256'] });
} catch {
    msg.sesion = null;
    msg.statusCode = 401;
    msg.payload = { mensaje: 'Inicia sesión de nuevo.' };
}
return msg;

if (!msg.sesion) return [null, msg];
const actual = msg.payload?.actual;
const nueva = msg.payload?.nueva;
const negar = (mensaje) => {
    msg.statusCode = 400;
    msg.payload = { mensaje };
    return [null, msg];
};
if (actual !== undefined && (typeof actual !== 'string' || actual === '')) {
    return negar('Escribe tu contraseña actual.');
}
if (typeof nueva !== 'string' || nueva.length < 8) {
    return negar('La contraseña debe tener al menos 8 caracteres.');
}
if (nueva.length > 72) {
    return negar('La contraseña puede tener hasta 72 caracteres.');
}
if (!/[A-Za-z]/.test(nueva) || !/[0-9]/.test(nueva)) {
    return negar('La contraseña debe tener letras y números.');
}
msg.claves = { actual, nueva };
msg.query = 'SELECT password_hash, debe_cambiar_clave, activo FROM usuarios WHERE id = $1';
msg.params = [msg.sesion.sub];
return [msg, null];

const u = msg.payload[0];
const { actual, nueva } = msg.claves;
delete msg.claves;
const negar = (estado, mensaje) => {
    msg.statusCode = estado;
    msg.payload = { mensaje };
